## Module: S3 Bucket

### `modules/s3-bucket/versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
```

### `modules/s3-bucket/variables.tf`

```hcl
variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
}

variable "environment" {
  description = "Deployment environment (dev/prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "enable_versioning" {
  description = "Whether to enable bucket versioning"
  type        = bool
  default     = true
}

variable "sse_algorithm" {
  description = "Server-side encryption algorithm (AES256 or aws:kms)"
  type        = string
  default     = "AES256"
  validation {
    condition     = contains(["AES256", "aws:kms"], var.sse_algorithm)
    error_message = "SSE algorithm must be 'AES256' or 'aws:kms'."
  }
}

variable "kms_key_arn" {
  description = "KMS key ARN for encryption (required if sse_algorithm is aws:kms)"
  type        = string
  default     = null
}

variable "enable_replication" {
  description = "Whether to enable cross-region replication"
  type        = bool
  default     = false
}

variable "replication_destination_region" {
  description = "Destination region for cross-region replication"
  type        = string
  default     = null
}

variable "replication_destination_bucket_name" {
  description = "Name of the destination replication bucket"
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}
```

### `modules/s3-bucket/main.tf`

```hcl
resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name

  tags = merge(var.tags, {
    Name = var.bucket_name
  })
}

resource "aws_s3_bucket_versioning" "this" {
  count = var.enable_versioning ? 1 : 0

  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_to_new_objects = true

    bucket_key_enabled = var.sse_algorithm == "aws:kms"

    sse_algorithm = var.sse_algorithm

    kms_master_key_id = var.sse_algorithm == "aws:kms" ? var.kms_key_arn : null
  }
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Lifecycle rules for noncurrent versions
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = var.enable_versioning ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"

    noncurrent_version_expiration {
      noncurrent_days = 30
    }

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "GLACIER"
    }
  }
}

# Replication configuration (prod only)
resource "aws_s3_bucket_replication" "this" {
  count = var.enable_replication ? 1 : 0

  role = var.enable_replication ? module.replication_role.iam_role_arn : null

  rule {
    id     = "replicate-to-${var.replication_destination_region}"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replication_destination.id
      storage_class = "STANDARD"
    }
  }
}

# Replication destination bucket (prod, cross-region)
resource "aws_s3_bucket" "replication_destination" {
  count = var.enable_replication ? 1 : 0

  bucket = var.replication_destination_bucket_name
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  count = var.enable_replication ? 1 : 0

  bucket = aws_s3_bucket.replication_destination[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replication_destination" {
  count = var.enable_replication ? 1 : 0

  bucket = aws_s3_bucket.replication_destination[0].id

  rule {
    apply_to_new_objects = true
    bucket_key_enabled   = var.sse_algorithm == "aws:kms"
    sse_algorithm        = var.sse_algorithm
    kms_master_key_id    = var.sse_algorithm == "aws:kms" ? var.kms_key_arn : null
  }
}

resource "aws_s3_bucket_public_access_block" "replication_destination" {
  count = var.enable_replication ? 1 : 0

  bucket = aws_s3_bucket.replication_destination[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Replication IAM role
module "replication_role" {
  source  = "../iam-role"
  count   = var.enable_replication ? 1 : 0

  role_name   = "${var.bucket_name}-replication-role"
  environment = var.environment
  tags        = var.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  inline_policies = {
    replication = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "s3:GetReplicationConfiguration",
            "s3:ListBucket"
          ]
          Resource = [
            aws_s3_bucket.this.arn,
            aws_s3_bucket.replication_destination[0].arn
          ]
        },
        {
          Effect = "Allow"
          Action = [
            "s3:GetObjectVersion",
            "s3:PutObject",
            "s3:PutObjectLegalHold",
            "s3:PutObjectVersionTagging",
            "s3:ReplicateObject"
          ]
          Resource = [
            "${aws_s3_bucket.replication_destination[0].arn}/object/*"
          ]
        }
      ]
    })
  }
}
```

### `modules/s3-bucket/outputs.tf`

```hcl
output "bucket_name" {
  description = "Name of the S3 bucket"
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the S3 bucket"
  value       = aws_s3_bucket.this.arn
}

output "bucket_region" {
  description = "Region of the S3 bucket"
  value       = aws_s3_bucket.this.region
}

output "replication_destination_bucket_name" {
  description = "Name of the replication destination bucket (if enabled)"
  value       = var.enable_replication ? var.replication_destination_bucket_name : null
}
```

