## Module: RDS PostgreSQL

### `modules/rds-postgres/versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}
```

### `modules/rds-postgres/variables.tf`

```hcl
variable "environment" {
  description = "Deployment environment (dev/prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "db_name" {
  description = "Name of the database"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for the database"
  type        = string
  default     = "appadmin"
}

variable "db_password" {
  description = "Master password for the database (should come from SOPS-encrypted tfvars)"
  type        = string
  sensitive   = true
}

variable "instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.micro"
}

variable "allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "db_engine_version" {
  description = "PostgreSQL engine version"
  type        = string
  default     = "16"
}

variable "multi_az" {
  description = "Enable Multi-AZ deployment"
  type        = bool
  default     = false
}

variable "storage_encrypted" {
  description = "Enable storage encryption"
  type        = bool
  default     = true
}

variable "backup_retention_days" {
  description = "Number of days to retain automated backups"
  type        = number
  default     = 7
  validation {
    condition     = var.backup_retention_days >= 7
    error_message = "Backup retention must be at least 7 days."
  }
}

variable "deletion_protection" {
  description = "Enable deletion protection"
  type        = bool
  default     = true
}

variable "vpc_security_group_ids" {
  description = "List of VPC security group IDs"
  type        = list(string)
}

variable "subnet_ids" {
  description = "List of VPC subnet IDs for the DB subnet group"
  type        = list(string)
}

variable "allowed_security_group_ids" {
  description = "Security group IDs allowed to connect to the DB"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}
```

### `modules/rds-postgres/main.tf`

```hcl
# Generate a unique suffix for resource naming
resource "random_id" "suffix" {
  byte_length = 4
  prefix      = ""
}

# DB Subnet Group
resource "aws_db_subnet_group" "this" {
  name       = "app-db-${var.environment}-${random_id.suffix.result}"
  subnet_ids = var.subnet_ids

  tags = merge(var.tags, {
    Name = "app-db-${var.environment}"
  })
}

# Security Group for the RDS instance
resource "aws_security_group" "rds" {
  name        = "rds-${var.environment}-${random_id.suffix.result}"
  description = "Allow PostgreSQL connections from application security groups"
  vpc_id      = data.aws_vpc.current.id

  ingress {
    description = "PostgreSQL"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = var.allowed_security_group_ids
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, {
    Name = "rds-${var.environment}"
  })
}

data "aws_vpc" "current" {
  default = true
}

# RDS PostgreSQL Instance
resource "aws_db_instance" "this" {
  identifier     = "app-${var.environment}-${random_id.suffix.result}"
  engine         = "postgres"
  engine_version = var.db_engine_version
  instance_class = var.instance_class

  allocated_storage     = var.allocated_storage
  max_allocated_storage = var.allocated_storage * 2

  db_name  = var.db_name
  username = var.db_username
  password = var.db_password

  multi_az                = var.multi_az
  storage_encrypted       = var.storage_encrypted
  storage_type            = "gp3"
  iops                    = var.instance_class != "db.t3.micro" ? 3000 : null
  backup_retention_period = var.backup_retention_days
  deletion_protection     = var.deletion_protection

  publicly_accessible = false

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  apply_immediately        = var.environment == "dev"
  skip_final_snapshot      = var.environment == "dev"
  final_snapshot_identifier = var.environment == "prod" ? "app-${var.environment}-final-${formatdate("YYYYMMDDHHmmss", timestamp())}" : null

  performance_insights_enabled = var.environment == "prod"
  performance_insights_retention_period = var.environment == "prod" ? 73 : null

  monitoring_interval = var.environment == "prod" ? 60 : 0

  tags = merge(var.tags, {
    Name = "app-${var.environment}"
  })
}
```

### `modules/rds-postgres/outputs.tf`

```hcl
output "endpoint" {
  description = "RDS endpoint (host:port)"
  value       = aws_db_instance.this.endpoint
}

output "host" {
  description = "RDS hostname"
  value       = aws_db_instance.this.address
}

output "port" {
  description = "RDS port"
  value       = aws_db_instance.this.port
}

output "db_name" {
  description = "Database name"
  value       = aws_db_instance.this.db_name
}

output "resource_id" {
  description = "RDS resource ID"
  value       = aws_db_instance.this.resource_id
}

output "security_group_id" {
  description = "Security group ID for the RDS instance"
  value       = aws_security_group.rds.id
}
```

