## Module: IAM Role

### `modules/iam-role/versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
```

### `modules/iam-role/variables.tf`

```hcl
variable "role_name" {
  description = "Name of the IAM role"
  type        = string
}

variable "environment" {
  description = "Deployment environment (dev/prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "assume_role_policy" {
  description = "JSON-encoded assume role policy document"
  type        = string
}

variable "inline_policies" {
  description = "Map of inline policy name to JSON-encoded policy document"
  type        = map(string)
  default     = {}
}

variable "managed_policy_arns" {
  description = "List of managed policy ARNs to attach"
  type        = list(string)
  default     = []
}

variable "max_session_duration" {
  description = "Maximum session duration in seconds"
  type        = number
  default     = 3600
}

variable "description" {
  description = "Role description"
  type        = string
  default     = ""
}

variable "permissions_boundary_arn" {
  description = "Permissions boundary policy ARN"
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply"
  type        = map(string)
  default     = {}
}
```

### `modules/iam-role/main.tf`

```hcl
resource "aws_iam_role" "this" {
  name               = var.role_name
  description        = var.description
  assume_role_policy = var.assume_role_policy
  max_session_duration = var.max_session_duration

  permissions_boundary = var.permissions_boundary_arn

  tags = merge(var.tags, {
    Name = var.role_name
  })
}

resource "aws_iam_role_policy" "inline" {
  for_each = var.inline_policies

  name   = each.key
  role   = aws_iam_role.this.name
  policy = each.value
}

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = toset(var.managed_policy_arns)

  role       = aws_iam_role.this.name
  policy_arn = each.value
}
```

### `modules/iam-role/outputs.tf`

```hcl
output "role_name" {
  description = "Name of the IAM role"
  value       = aws_iam_role.this.name
}

output "role_arn" {
  description = "ARN of the IAM role"
  value       = aws_iam_role.this.arn
}

output "role_id" {
  description = "ID of the IAM role"
  value       = aws_iam_role.this.id
}
```

