## Environment: Dev

### `environments/dev/versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
```

### `environments/dev/backend.tf`

```hcl
terraform {
  backend "s3" {
    bucket         = "myorg-terraform-state"
    key            = "dev/infra.tfstate"
    region         = "us-east-1"
    dynamodb_table = "myorg-terraform-locks"
    encrypt        = true
  }
}
```

### `environments/dev/variables.tf`

```hcl
variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Project name for resource naming"
  type        = string
  default     = "myapp"
}

variable "vpc_id" {
  description = "VPC ID for resource placement"
  type        = string
}

variable "subnet_ids" {
  description = "Subnet IDs for RDS"
  type        = list(string)
}

variable "app_security_group_ids" {
  description = "Security group IDs for application (allowed to connect to RDS)"
  type        = list(string)
  default     = []
}

variable "db_password" {
  description = "RDS master password (inject via SOPS-decrypted tfvars)"
  type        = string
  sensitive   = true
}

variable "oidc_provider_arn" {
  description = "OIDC provider ARN for IAM trust (null in dev)"
  type        = string
  default     = null
}

variable "oidc_namespace" {
  description = "OIDC namespace claim value"
  type        = string
  default     = ""
}
```

### `environments/dev/main.tf`

```hcl
provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = var.project_name
      Environment = "dev"
      ManagedBy   = "terraform"
    }
  }
}

# ─── S3 Bucket ───────────────────────────────────────────────────────────────

module "s3" {
  source = "../../modules/s3-bucket"

  bucket_name  = "${var.project_name}-assets-dev"
  environment  = "dev"
  enable_versioning = true
  sse_algorithm  = "AES256"

  # Replication is prod-only
  enable_replication = false

  tags = {}
}

# ─── RDS PostgreSQL ──────────────────────────────────────────────────────────

module "rds" {
  source = "../../modules/rds-postgres"

  environment    = "dev"
  instance_class = "db.t3.micro"
  allocated_storage = 20
  multi_az         = false
  storage_encrypted = true
  backup_retention_days = 7
  deletion_protection   = true

  vpc_security_group_ids = var.app_security_group_ids
  subnet_ids             = var.subnet_ids
  allowed_security_group_ids = var.app_security_group_ids

  db_password = var.db_password
}

# ─── IAM Role (Service Account) ──────────────────────────────────────────────

# Dev: trust EC2 service (workload runs on nodes)
module "iam" {
  source = "../../modules/iam-role"

  role_name   = "${var.project_name}-service-role-dev"
  environment = "dev"
  description = "Service account role for ${var.project_name} (dev)"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  inline_policies = {
    s3_access = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Sid    = "S3ReadAssets"
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:ListBucket"
          ]
          Resource = [
            module.s3.bucket_arn,
            "${module.s3.bucket_arn}/*"
          ]
        },
        {
          Sid    = "S3WriteAssets"
          Effect = "Allow"
          Action = [
            "s3:PutObject"
          ]
          Resource = [
            "${module.s3.bucket_arn}/*"
          ]
        }
      ]
    })
  }

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/AmazonEKSRole"
  ]
}
```

### `environments/dev/outputs.tf`

```hcl
output "s3_bucket_name" {
  description = "S3 bucket name"
  value       = module.s3.bucket_name
}

output "s3_bucket_arn" {
  description = "S3 bucket ARN"
  value       = module.s3.bucket_arn
}

output "rds_endpoint" {
  description = "RDS endpoint"
  value       = module.rds.endpoint
}

output "rds_host" {
  description = "RDS host"
  value       = module.rds.host
}

output "rds_port" {
  description = "RDS port"
  value       = module.rds.port
}

output "iam_role_arn" {
  description = "IAM service role ARN"
  value       = module.iam.role_arn
}
```

### `environments/dev/terraform.tfvars`

```hcl
# Plain tfvars for non-sensitive values.
# Sensitive values (db_password) come from secrets/dev.tfvars.enc

vpc_id     = "vpc-0123456789abcdef0"
subnet_ids = ["subnet-aaa111", "subnet-bbb222"]

app_security_group_ids = ["sg-12345678"]
```

### `environments/dev/README.md` (for SOPS decryption)

```
To decrypt secrets:
  sops -d ../../secrets/dev.tfvars.enc > terraform.tfvars.decrypted

Then run:
  terraform apply -var-file terraform.tfvars.decrypted

The .decrypted file must be in .gitignore.
```

