```

### `environments/prod/variables.tf`

```hcl
variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-west-2"
}

variable "project_name" {
  description = "Project name for resource naming"
  type        = string
  default     = "myapp"
}

variable "vpc_id" {
  description = "VPC ID for resource placement"
  type        = string
}

variable "subnet_ids" {
  description = "Subnet IDs for RDS (at least 2 AZs)"
  type        = list(string)
}

variable "app_security_group_ids" {
  description = "Security group IDs for application (allowed to connect to RDS)"
  type        = list(string)
  default     = []
}

variable "db_password" {
  description = "RDS master password (inject via SOPS-decrypted tfvars)"
  type        = string
  sensitive   = true
